const escapeRegex = (value) => value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

const escapedPhrases = ingredientPhrases
  .sort(([first], [second]) => second.length - first.length)
  .map(([source, translation]) => {
    const leftBoundary = /^\w/.test(source) ? '\\b' : '';
    const rightBoundary = /\w$/.test(source) ? '\\b' : '';
    return [
      new RegExp(`${leftBoundary}${escapeRegex(source)}${rightBoundary}`, 'gi'),
      translation,
    ];
  });

export function localizeUntranslatedIngredient(value) {
  if (typeof value !== 'string' || !value) return value;

  let result = value
    .replace(/\bPinch of\s*/i, 'Una pizca de ')
    .replace(/\bSplash of\s*/i, 'Un chorrito de ')
    .replace(/\bPinch\s+/i, 'Pizca de ')
    .replace(/\bdivided\b/gi, 'por separado')
    .replace(/\bplus more for serving\b/gi, 'y un poco más para servir')
    .replace(/\bplus more\b/gi, 'y un poco más')
    .replace(/\bfor serving\b/gi, 'para servir')
    .replace(/\bzested\b/gi, 'con ralladura');

  for (const [pattern, translation] of escapedPhrases) {
    result = result.replace(pattern, translation);
  }

  result = result
    .replace(/^(\d+(?:\s+\d+\/\d+|\/\d+)?)\s+tbsp\.?\s+plus\s+(\d+(?:\s+\d+\/\d+|\/\d+)?)\s+tsp\.?\s*/i, '$1 cda. más $2 cdta. de ')
    .replace(/^(\d+(?:\s+\d+\/\d+|\/\d+)?)\s+cup\s+plus\s+(\d+(?:\s+\d+\/\d+|\/\d+)?)\s+tbsp\.?\s*/i, '$1 taza más $2 cdas. de ')
    .replace(/^(\d+(?:\s+\d+\/\d+|\/\d+)?)\s+(tsp\.?|tbsp\.?|cups?|lb\.?|oz\.?|qt\.?|pkg\.?|L)\s*/i, (match, amount, unit) => {
      const localizedUnit = {
        tsp: 'cdta.',
        tbsp: 'cda.',
        cup: 'taza',
        cups: 'tazas',
        lb: 'lb',
        oz: 'oz',
        qt: 'cuarto',
        pkg: 'paquete',
        l: 'L',
      }[unit.toLowerCase().replace(/\.$/, '')];
      return `${amount} ${localizedUnit} de `;
    })
    .replace(/^(\d+)\s+dashes?\b/i, '$1 gotas de')
    .replace(/^(\d+(?:\/\d+)?)\s+parts?\b/i, '$1 partes de')
    .replace(/\bbottle\b/gi, 'botella de')
    .replace(/\btube\b/gi, 'tubo de')
    .replace(/\bcontainer\b/gi, 'envase de')
    .replace(/\bpkg\.?\b/gi, 'paquete')
    .replace(/\b(cda|cdta)\. de sin sal\b/gi, '$1. sin sal')
    .replace(/\s+de\s+de\s+/gi, ' de ')
    .replace(/\s+/g, ' ')
    .trim();

  return result;
}
